namespace sv_83351de1953a41de8b8f3413cf812051.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one instance per circuit) that holds theme state.
/// Interactive components subscribe to OnChange to react to updates.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        Services.ThemeMode.Light => "☀️",
        Services.ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" @bind="SelectedTheme">
        <option value="@Services.ThemeMode.Light">Light</option>
        <option value="@Services.ThemeMode.Dark">Dark</option>
        <option value="@Services.ThemeMode.System">System</option>
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color" @bind="AccentColor" />
</div>

<div class="mt-4 p-3 border rounded" style="border-color: @ThemeService.AccentColor !important;">
    <strong>Preview:</strong> Current theme is <em>@ThemeService.Theme</em> with accent
    <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</div>

@code {
    private Services.ThemeMode SelectedTheme
    {
        get => ThemeService.Theme;
        set => ThemeService.Theme = value;
    }

    private string AccentColor
    {
        get => ThemeService.AccentColor;
        set => ThemeService.AccentColor = value;
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

